<template><view class="page"><view class="profile card"><text class="avatar">{{user?.username?.[0]||'念'}}</text><view><text class="card-title">{{user?.username}}</text><text class="muted">{{user?.email}}</text><view><text v-for="role in user?.roles||[]" :key="role" class="badge active">{{role==='admin'?'管理员':role==='member'?'普通用户':role}}</text></view></view></view><view class="card"><view class="row between"><text>账号状态</text><text class="badge active">{{user?.status||'active'}}</text></view></view><button class="danger" @click="logout">退出登录</button></view></template>
<script setup>import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{api,getSession,saveSession}from'../../api';const user=ref(getSession()?.user);onShow(async()=>{try{user.value=await api.me()}catch{}});async function logout(){try{await api.logout()}catch{}saveSession(null);uni.reLaunch({url:'/pages/login/login'})}</script>
<style scoped>.profile{display:flex;align-items:center;gap:24rpx}.avatar{display:grid;place-items:center;width:118rpx;height:118rpx;border-radius:50%;background:#ead9c7;color:#a94439;font-size:48rpx;font-weight:700}.profile .muted{display:block;margin:8rpx 0 15rpx}.profile .badge{margin-right:8rpx}</style>
